var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
var roots = scene.GetRootGameObjects();
Sim.PhoneControllerUI phone = null;
foreach (var r in roots) { phone = r.GetComponentInChildren<Sim.PhoneControllerUI>(true); if (phone != null) break; }
var phoneTr = phone.transform;

// Find the Home screen and list its children (which include the app buttons)
var home = phoneTr.Find("Home");
if (home != null) {
    Debug.Log("Home childCount=" + home.childCount);
    foreach (var btn in home.GetComponentsInChildren<PhoneApplicationButton>(true)) {
        string p = btn.transform.name;
        var t = btn.transform; while (t.parent != null && t.parent != home) { t = t.parent; p = t.name + "/" + p; }
        var appField = typeof(PhoneApplicationButton).GetField("application", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        var appVal = appField != null ? appField.GetValue(btn) : null;
        Debug.Log("  Btn: " + p + " application=" + (appVal != null ? appVal.GetType().Name + "#" + ((UnityEngine.Object)appVal).GetInstanceID() : "null"));
    }
}

// Dump PhoneControllerUI.applications list
var apps = typeof(Sim.PhoneControllerUI).GetField("applications", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
var list = apps != null ? apps.GetValue(phone) as System.Collections.IList : null;
Debug.Log("PhoneControllerUI.applications.Count=" + (list != null ? list.Count : -1));
if (list != null) for (int i = 0; i < list.Count; i++) {
    var item = list[i] as PhoneApplicationButton;
    Debug.Log("  [" + i + "] " + (item != null ? item.name + " iid=" + item.GetInstanceID() : "null"));
}
